    "\u0041\u0075\u0074\u006f\u0020\u004c\u006f\u0067\u0069\u006e": "\u062a\u0633\u062c\u064a\u0644\u0020\u062f\u062e\u0648\u0644\u0020\u062a\u0644\u0642\u0627\u0626\u064a",
    "\u0045\u006e\u0061\u0062\u006c\u0065\u0020\u0064\u0069\u0072\u0065\u0063\u0074\u0020\u0049\u0050\u0020\u0061\u0063\u0063\u0065\u0073\u0073": "\u062a\u0641\u0639\u064a\u0644\u0020\u0627\u0644\u0648\u0635\u0648\u0644\u0020\u0627\u0644\u0645\u0628\u0627\u0634\u0631\u0020\u0644\u0639\u0646\u0648\u0627\u0646\u0020\u0049\u0050",
    "\u0052\u0065\u006e\u0061\u006d\u0065": "\u0627\u0639\u0627\u062f\u0629\u0020\u062a\u0633\u0645\u064a\u0629",
