    "\u0043\u0068\u0061\u006e\u0067\u0065\u0020\u0050\u0061\u0074\u0068": "\u062a\u063a\u064a\u064a\u0631\u0020\u0627\u0644\u0645\u0633\u0627\u0631",
    "\u0043\u0072\u0065\u0061\u0074\u0065\u0020\u0046\u006f\u006c\u0064\u0065\u0072": "\u0627\u0646\u0634\u0627\u0621\u0020\u0645\u062c\u0644\u062f",
    "\u0050\u006c\u0065\u0061\u0073\u0065\u0020\u0065\u006e\u0074\u0065\u0072\u0020\u0074\u0068\u0065\u0020\u0066\u006f\u006c\u0064\u0065\u0072\u0020\u006e\u0061\u006d\u0065": "\u0627\u0644\u0631\u062c\u0627\u0621\u0020\u0627\u062f\u062e\u0627\u0644\u0020\u0627\u0633\u0645\u0020\u0627\u0644\u0645\u062c\u0644\u062f",
