    "\u0043\u006f\u006e\u006e\u0065\u0063\u0074\u0020\u0076\u0069\u0061\u0020\u0072\u0065\u006c\u0061\u0079": "\u0627\u0644\u0627\u062a\u0635\u0627\u0644\u0020\u0639\u0628\u0631\u0020\u0648\u0633\u064a\u0637",
