    "\u0044\u0069\u0073\u0063\u006f\u0076\u0065\u0072\u0065\u0064": "\u0627\u0644\u0645\u0643\u062a\u0634\u0641\u0629",
    "\u0069\u006e\u0073\u0074\u0061\u006c\u006c\u005f\u0064\u0061\u0065\u006d\u006f\u006e\u005f\u0074\u0069\u0070": "\u0644\u0644\u0628\u062f\u0621\u0020\u0645\u0639\u0020\u0628\u062f\u0621\u0020\u062a\u0634\u063a\u064a\u0644\u0020\u0627\u0644\u0646\u0638\u0627\u0645\u002e\u0020\u062a\u062d\u062a\u0627\u062c\u0020\u0627\u0644\u0649\u0020\u062a\u062b\u0628\u064a\u062a\u0020\u062e\u062f\u0645\u0629\u0020\u0627\u0644\u0646\u0638\u0627\u0645\u002e",
    "\u0052\u0065\u006d\u006f\u0074\u0065\u0020\u0049\u0044": "\u0627\u0644\u0645\u0639\u0631\u0641\u0020\u0627\u0644\u0628\u0639\u064a\u062f",
