    "\u0049\u006e\u0070\u0075\u0074\u0020\u0043\u006f\u006e\u0074\u0072\u006f\u006c": "\u062a\u062d\u0643\u0645\u0020\u0627\u0644\u0627\u062f\u062e\u0627\u0644",
    "\u0041\u0075\u0064\u0069\u006f\u0020\u0043\u0061\u0070\u0074\u0075\u0072\u0065": "\u0644\u0642\u0637\u0020\u0627\u0644\u0635\u0648\u062a",
    "\u0044\u006f\u0020\u0079\u006f\u0075\u0020\u0061\u0063\u0063\u0065\u0070\u0074\u003f": "\u0647\u0644\u0020\u062a\u0642\u0628\u0644\u061f",
    "\u004f\u0070\u0065\u006e\u0020\u0053\u0079\u0073\u0074\u0065\u006d\u0020\u0053\u0065\u0074\u0074\u0069\u006e\u0067": "\u0641\u062a\u062d\u0020\u0627\u0639\u062f\u0627\u062f\u0627\u062a\u0020\u0627\u0644\u0646\u0638\u0627\u0645",
