    "\u0055\u006e\u0073\u0075\u0070\u0070\u006f\u0072\u0074\u0065\u0064": "\u063a\u064a\u0631\u0020\u0645\u062f\u0639\u0648\u0645",
    "\u0050\u0065\u0065\u0072\u0020\u0064\u0065\u006e\u0069\u0065\u0064": "\u0627\u0644\u0642\u0631\u064a\u0646\u0020\u0631\u0641\u0636",
