    "\u0043\u006f\u006c\u006c\u0061\u0070\u0073\u0065\u0020\u0074\u006f\u006f\u006c\u0062\u0061\u0072": "\u0637\u064a\u0020\u0634\u0631\u064a\u0637\u0020\u0627\u0644\u0627\u062f\u0648\u0627\u062a",
