    "\u0041\u006c\u0072\u0065\u0061\u0064\u0079\u0020\u0065\u0078\u0069\u0073\u0074\u0073": "\u0645\u0648\u062c\u0648\u062f\u0020\u0645\u0633\u0628\u0642\u0627",
    "\u0043\u0068\u0061\u006e\u0067\u0065\u0020\u0050\u0061\u0073\u0073\u0077\u006f\u0072\u0064": "\u062a\u063a\u064a\u064a\u0631\u0020\u0643\u0644\u0645\u0629\u0020\u0627\u0644\u0645\u0631\u0648\u0631",
