    "\u0050\u0072\u0069\u006d\u0061\u0072\u0079\u0020\u0043\u006f\u006c\u006f\u0072": "\u0627\u0644\u0644\u0648\u0646\u0020\u0627\u0644\u0623\u0633\u0627\u0633\u064a",
    "\u0048\u0053\u0056\u0020\u0043\u006f\u006c\u006f\u0072": "\u0627\u0644\u0644\u0648\u0646\u0020\u0628\u0646\u0638\u0627\u0645\u0020\u0048\u0053\u0056",
