    "\u0049\u006e\u0073\u0074\u0061\u006c\u006c\u0061\u0074\u0069\u006f\u006e\u0020\u0066\u0061\u0069\u006c\u0065\u0064\u0021": "\u0641\u0634\u0644\u0020\u0627\u0644\u062a\u062b\u0628\u064a\u062a\u0021",
    "\u0052\u0065\u0076\u0065\u0072\u0073\u0065\u0020\u006d\u006f\u0075\u0073\u0065\u0020\u0077\u0068\u0065\u0065\u006c": "\u0639\u0643\u0633\u0020\u0639\u062c\u0644\u0629\u0020\u0627\u0644\u0645\u0627\u0648\u0633",
    "\u007b\u007d\u0020\u0073\u0065\u0073\u0073\u0069\u006f\u006e\u0073": "\u007b\u007d\u0020\u062c\u0644\u0633\u0627\u062a",
