    "\u0073\u0063\u0061\u006d\u005f\u0074\u0065\u0078\u0074\u0031": "\u062a\u062d\u0630\u064a\u0631\u0021\u0020\u0647\u0630\u0627\u0020\u0642\u062f\u0020\u064a\u0643\u0648\u0646\u0020\u0647\u062c\u0648\u0645\u0020\u0627\u062d\u062a\u064a\u0627\u0644\u064a\u002e",
    "\u0073\u0063\u0061\u006d\u005f\u0074\u0065\u0078\u0074\u0032": "\u064a\u0631\u062c\u0649\u0020\u062a\u0648\u062e\u064a\u0020\u0627\u0644\u062d\u0630\u0631\u0020\u0648\u0639\u062f\u0645\u0020\u0627\u0644\u0645\u0648\u0627\u0641\u0642\u0629\u0020\u0639\u0644\u0649\u0020\u0627\u0644\u0627\u062a\u0635\u0627\u0644\u0020\u0625\u0630\u0627\u0020\u0643\u0646\u062a\u0020\u063a\u064a\u0631\u0020\u0645\u062a\u0623\u0643\u062f\u002e",
    "\u0044\u006f\u006e\u0027\u0074\u0020\u0073\u0068\u006f\u0077\u0020\u0061\u0067\u0061\u0069\u006e": "\u0644\u0627\u0020\u062a\u0638\u0647\u0631\u0020\u0645\u0631\u0629\u0020\u0623\u062e\u0631\u0649",
