    "\u0053\u0065\u006c\u0065\u0063\u0074\u0020\u0061\u0020\u0070\u0065\u0065\u0072": "\u0412\u044b\u0431\u0435\u0440\u044b\u0446\u0435\u0020\u0430\u0434\u0434\u0430\u043b\u0435\u043d\u044b\u0020\u045e\u0437\u0435\u043b",
    "\u0053\u0065\u006c\u0065\u0063\u0074\u0020\u0070\u0065\u0065\u0072\u0073": "\u0412\u044b\u0431\u0435\u0440\u044b\u0446\u0435\u0020\u0430\u0434\u0434\u0430\u043b\u0435\u043d\u044b\u044f\u0020\u045e\u0437\u043b\u044b",
