    "\u004e\u0065\u0074\u0077\u006f\u0072\u006b\u0020\u0065\u0072\u0072\u006f\u0072": "\u041c\u0440\u0435\u0436\u043e\u0432\u0430\u0020\u0433\u0440\u0435\u0448\u043a\u0430",
    "\u0055\u0073\u0065\u0072\u006e\u0061\u006d\u0065\u0020\u006d\u0069\u0073\u0073\u0065\u0064": "\u041b\u0438\u043f\u0441\u0432\u0430\u0020\u043f\u043e\u0442\u0440\u0435\u0431\u0438\u0442\u0435\u043b\u0441\u043a\u043e\u0020\u0438\u043c\u0435",
    "\u0050\u0061\u0073\u0073\u0077\u006f\u0072\u0064\u0020\u006d\u0069\u0073\u0073\u0065\u0064": "\u041b\u0438\u043f\u0441\u0432\u0430\u0020\u043f\u0430\u0440\u043e\u043b\u0430",
