    "\u004c\u0065\u0066\u0074\u0020\u004d\u006f\u0075\u0073\u0065": "\u041b\u044f\u0432\u0020\u0431\u0443\u0442\u043e\u043d\u0020\u043d\u0430\u0020\u043c\u0438\u0448\u043a\u0430\u0442\u0430",
