    "\u0053\u0068\u0061\u0072\u0065\u0020\u0073\u0063\u0072\u0065\u0065\u006e": "\u0421\u043f\u043e\u0434\u0435\u043b\u0438\u0020\u0435\u043a\u0440\u0430\u043d",
