    "\u0052\u0065\u006d\u006f\u0076\u0065": "\u0045\u006e\u0074\u0066\u0065\u0072\u006e\u0065\u006e",
    "\u0052\u0065\u0066\u0072\u0065\u0073\u0068\u0020\u0072\u0061\u006e\u0064\u006f\u006d\u0020\u0070\u0061\u0073\u0073\u0077\u006f\u0072\u0064": "\u005a\u0075\u0066\u00e4\u006c\u006c\u0069\u0067\u0065\u0073\u0020\u0050\u0061\u0073\u0073\u0077\u006f\u0072\u0074\u0020\u0065\u0072\u007a\u0065\u0075\u0067\u0065\u006e",
    "\u0053\u0065\u0074\u0020\u0079\u006f\u0075\u0072\u0020\u006f\u0077\u006e\u0020\u0070\u0061\u0073\u0073\u0077\u006f\u0072\u0064": "\u0045\u0069\u0067\u0065\u006e\u0065\u0073\u0020\u0050\u0061\u0073\u0073\u0077\u006f\u0072\u0074\u0020\u0066\u0065\u0073\u0074\u006c\u0065\u0067\u0065\u006e",
