    "\u004c\u0065\u0066\u0074\u0020\u004d\u006f\u0075\u0073\u0065": "\u004c\u0065\u0066\u0074\u0020\u006d\u006f\u0075\u0073\u0065",
    "\u004f\u006e\u0065\u002d\u004c\u006f\u006e\u0067\u0020\u0054\u0061\u0070": "\u004f\u006e\u0065\u002d\u006c\u006f\u006e\u0067\u0020\u0074\u0061\u0070",
    "\u0054\u0077\u006f\u002d\u0046\u0069\u006e\u0067\u0065\u0072\u0020\u0054\u0061\u0070": "\u0054\u0077\u006f\u002d\u0066\u0069\u006e\u0067\u0065\u0072\u0020\u0074\u0061\u0070",
    "\u0052\u0069\u0067\u0068\u0074\u0020\u004d\u006f\u0075\u0073\u0065": "\u0052\u0069\u0067\u0068\u0074\u0020\u006d\u006f\u0075\u0073\u0065",
    "\u004f\u006e\u0065\u002d\u0046\u0069\u006e\u0067\u0065\u0072\u0020\u004d\u006f\u0076\u0065": "\u004f\u006e\u0065\u002d\u0066\u0069\u006e\u0067\u0065\u0072\u0020\u006d\u006f\u0076\u0065",
