    "\u0054\u0077\u006f\u002d\u0046\u0069\u006e\u0067\u0065\u0072\u0020\u004d\u006f\u0076\u0065": "\u0054\u0077\u006f\u002d\u0066\u0069\u006e\u0067\u0065\u0072\u0020\u006d\u006f\u0076\u0065",
    "\u0043\u0061\u006e\u0076\u0061\u0073\u0020\u004d\u006f\u0076\u0065": "\u0043\u0061\u006e\u0076\u0061\u0073\u0020\u006d\u006f\u0076\u0065",
    "\u0050\u0069\u006e\u0063\u0068\u0020\u0074\u006f\u0020\u005a\u006f\u006f\u006d": "\u0050\u0069\u006e\u0063\u0068\u0020\u0074\u006f\u0020\u007a\u006f\u006f\u006d",
