    "\u0053\u006b\u0069\u0070": "\u0049\u0067\u006e\u006f\u0072\u0069",
    "\u0043\u006c\u006f\u0073\u0065": "\u0046\u0065\u0072\u006d\u0069",
    "\u0052\u0065\u0074\u0072\u0079": "\u0052\u0065\u0070\u0072\u006f\u0076\u0069",
    "\u004f\u004b": "\u004b\u006f\u006e\u0066\u0065\u0072\u006d\u0069",
    "\u0050\u0061\u0073\u0073\u0077\u006f\u0072\u0064\u0020\u0052\u0065\u0071\u0075\u0069\u0072\u0065\u0064": "\u0050\u0061\u0073\u0076\u006f\u0072\u0074\u006f\u0020\u0064\u0065\u0076\u0069\u0067\u0061",
    "\u0050\u006c\u0065\u0061\u0073\u0065\u0020\u0065\u006e\u0074\u0065\u0072\u0020\u0079\u006f\u0075\u0072\u0020\u0070\u0061\u0073\u0073\u0077\u006f\u0072\u0064": "\u0042\u006f\u006e\u0076\u006f\u006c\u0075\u0020\u0074\u0061\u006a\u0070\u0069\u0020\u0076\u0069\u0061\u006e\u0020\u0070\u0061\u0073\u0076\u006f\u0072\u0074\u006f\u006e",
    "\u0052\u0065\u006d\u0065\u006d\u0062\u0065\u0072\u0020\u0070\u0061\u0073\u0073\u0077\u006f\u0072\u0064": "\u004d\u0065\u006d\u006f\u0072\u0069\u0020\u0070\u0061\u0073\u0076\u006f\u0072\u0074\u006f\u006e",
