    "\u004f\u0072\u0069\u0067\u0069\u006e\u0061\u006c": "\u004f\u0072\u0069\u0067\u0069\u006e\u0061\u006c\u0061\u0020\u0072\u0069\u006c\u0061\u0074\u0075\u006d\u006f",
    "\u0053\u0068\u0072\u0069\u006e\u006b": "\u015c\u0072\u0075\u006d\u0070\u0069",
    "\u0053\u0074\u0072\u0065\u0074\u0063\u0068": "\u0053\u0074\u0072\u0065\u0109\u0069",
