    "\u0043\u0068\u0061\u006e\u0067\u0065\u0020\u0050\u0061\u0074\u0068": "\u015c\u0061\u006e\u011d\u0069\u0020\u0076\u006f\u006a\u006f\u006e",
    "\u0043\u0072\u0065\u0061\u0074\u0065\u0020\u0046\u006f\u006c\u0064\u0065\u0072": "\u004b\u0072\u0065\u0069\u0020\u0064\u006f\u0073\u0069\u0065\u0072\u0075\u006a\u006f\u006e",
