    "\u0046\u0069\u0078\u0020\u0069\u0074": "\u0052\u0069\u0070\u0061\u0072\u0075\u0020\u011d\u0069\u006e",
    "\u0057\u0061\u0072\u006e\u0069\u006e\u0067": "\u0041\u0076\u0065\u0072\u0074\u006f",
