    "\u0053\u0074\u0061\u0072\u0074\u0020\u0073\u0065\u0072\u0076\u0069\u0063\u0065": "\u0627\u062c\u0631\u0627\u06cc\u0020\u0633\u0631\u0648\u06cc\u0633",
