    "\u0050\u0072\u0069\u0076\u0061\u0063\u0079\u0020\u0053\u0074\u0061\u0074\u0065\u006d\u0065\u006e\u0074": "\u0628\u06cc\u0627\u0646\u06cc\u0647\u0020\u062d\u0631\u06cc\u0645\u0020\u062e\u0635\u0648\u0635\u06cc",
