    "\u0048\u006f\u006d\u0065": "\u0635\u0641\u062d\u0647\u0020\u0627\u0635\u0644\u06cc",
    "\u0041\u0075\u0064\u0069\u006f\u0020\u0049\u006e\u0070\u0075\u0074": "\u0648\u0631\u0648\u062f\u06cc\u0020\u0635\u062f\u0627",
    "\u0045\u006e\u0068\u0061\u006e\u0063\u0065\u006d\u0065\u006e\u0074\u0073": "\u0628\u0647\u0628\u0648\u062f\u0647\u0627",
