    "\u0056\u0065\u0072\u0073\u0069\u006f\u006e": "\u05d2\u05e8\u05e1\u05d4",
    "\u0048\u006f\u006d\u0065": "\u05d1\u05d9\u05ea",
    "\u0041\u0075\u0064\u0069\u006f\u0020\u0049\u006e\u0070\u0075\u0074": "\u05e7\u05dc\u05d8\u0020\u05e9\u05de\u05e2",
