    "\u0055\u006e\u006c\u006f\u0063\u006b\u0020\u004e\u0065\u0074\u0077\u006f\u0072\u006b\u0020\u0053\u0065\u0074\u0074\u0069\u006e\u0067\u0073": "\u004f\u0074\u006b\u006c\u006a\u0075\u010d\u0061\u006a\u0020\u0070\u006f\u0073\u0074\u0061\u0076\u006b\u0065\u0020\u006d\u0072\u0065\u017e\u0065",
    "\u0053\u0065\u0072\u0076\u0065\u0072": "\u0050\u006f\u0073\u006c\u0075\u017e\u0069\u0074\u0065\u006c\u006a",
    "\u0044\u0069\u0072\u0065\u0063\u0074\u0020\u0049\u0050\u0020\u0041\u0063\u0063\u0065\u0073\u0073": "\u0049\u007a\u0072\u0061\u0076\u0061\u006e\u0020\u0049\u0050\u0020\u0070\u0072\u0069\u0073\u0074\u0075\u0070",
    "\u0050\u0072\u006f\u0078\u0079": "\u0050\u0072\u006f\u0078\u0079",
    "\u0041\u0070\u0070\u006c\u0079": "\u0050\u0072\u0069\u006d\u0069\u006a\u0065\u006e\u0069",
