    "\u0055\u006e\u0070\u0069\u006e\u0020\u0054\u006f\u006f\u006c\u0062\u0061\u0072": "\u004f\u0074\u006b\u0076\u0061\u010d\u0069\u0020\u0061\u006c\u0061\u0074\u006e\u0075\u0020\u0074\u0072\u0061\u006b\u0075",
    "\u0052\u0065\u0063\u006f\u0072\u0064\u0069\u006e\u0067": "\u0053\u006e\u0069\u006d\u0061\u006e\u006a\u0065",
