    "\u0055\u0073\u0065\u0072\u006e\u0061\u006d\u0065": "\u004e\u0061\u006d\u0061\u0020\u0070\u0065\u006e\u0067\u0067\u0075\u006e\u0061",
    "\u0049\u006e\u0076\u0061\u006c\u0069\u0064\u0020\u0070\u006f\u0072\u0074": "\u004b\u0065\u0073\u0061\u006c\u0061\u0068\u0061\u006e\u0020\u0070\u006f\u0072\u0074",
