    "\u004c\u006f\u0063\u0061\u006c": "\u004c\u006f\u0063\u0061\u006c\u0065",
    "\u0052\u0065\u006d\u006f\u0074\u0065": "\u0052\u0065\u006d\u006f\u0074\u006f",
    "\u0052\u0065\u006d\u006f\u0074\u0065\u0020\u0043\u006f\u006d\u0070\u0075\u0074\u0065\u0072": "\u0043\u006f\u006d\u0070\u0075\u0074\u0065\u0072\u0020\u0072\u0065\u006d\u006f\u0074\u006f",
    "\u004c\u006f\u0063\u0061\u006c\u0020\u0043\u006f\u006d\u0070\u0075\u0074\u0065\u0072": "\u0043\u006f\u006d\u0070\u0075\u0074\u0065\u0072\u0020\u006c\u006f\u0063\u0061\u006c\u0065",
    "\u0043\u006f\u006e\u0066\u0069\u0072\u006d\u0020\u0044\u0065\u006c\u0065\u0074\u0065": "\u0043\u006f\u006e\u0066\u0065\u0072\u006d\u0061\u0020\u0065\u006c\u0069\u006d\u0069\u006e\u0061\u007a\u0069\u006f\u006e\u0065",
