    "\u0050\u0072\u0069\u0076\u0061\u0063\u0079\u0020\u006d\u006f\u0064\u0065": "\u004d\u006f\u0064\u0061\u006c\u0069\u0074\u00e0\u0020\u0070\u0072\u0069\u0076\u0061\u0063\u0079",
    "\u0042\u006c\u006f\u0063\u006b\u0020\u0075\u0073\u0065\u0072\u0020\u0069\u006e\u0070\u0075\u0074": "\u0042\u006c\u006f\u0063\u0063\u0061\u0020\u0069\u006e\u0070\u0075\u0074\u0020\u0075\u0074\u0065\u006e\u0074\u0065",
    "\u0055\u006e\u0062\u006c\u006f\u0063\u006b\u0020\u0075\u0073\u0065\u0072\u0020\u0069\u006e\u0070\u0075\u0074": "\u0053\u0062\u006c\u006f\u0063\u0063\u0061\u0020\u0069\u006e\u0070\u0075\u0074\u0020\u0075\u0074\u0065\u006e\u0074\u0065",
