    "\u0054\u0065\u0072\u006d\u0069\u006e\u0061\u006c": "\u30bf\u30fc\u30df\u30ca\u30eb",
    "\u0045\u006e\u0061\u0062\u006c\u0065\u0020\u0074\u0065\u0072\u006d\u0069\u006e\u0061\u006c": "\u30bf\u30fc\u30df\u30ca\u30eb\u3092\u6709\u52b9\u5316\u3059\u308b",
    "\u004e\u0065\u0077\u0020\u0074\u0061\u0062": "\u65b0\u3057\u3044\u30bf\u30d6",
