    "\u0055\u0073\u0065\u0020\u0070\u0065\u0072\u006d\u0061\u006e\u0065\u006e\u0074\u0020\u0070\u0061\u0073\u0073\u0077\u006f\u0072\u0064": "\uc601\uad6c\u0020\ube44\ubc00\ubc88\ud638\u0020\uc0ac\uc6a9",
    "\u0055\u0073\u0065\u0020\u0062\u006f\u0074\u0068\u0020\u0070\u0061\u0073\u0073\u0077\u006f\u0072\u0064\u0073": "\ub450\u0020\uac00\uc9c0\u0020\ube44\ubc00\ubc88\ud638\u0020\ubaa8\ub450\u0020\uc0ac\uc6a9",
    "\u0053\u0065\u0074\u0020\u0070\u0065\u0072\u006d\u0061\u006e\u0065\u006e\u0074\u0020\u0070\u0061\u0073\u0073\u0077\u006f\u0072\u0064": "\uc601\uad6c\u0020\ube44\ubc00\ubc88\ud638\u0020\uc124\uc815",
    "\u0045\u006e\u0061\u0062\u006c\u0065\u0020\u0072\u0065\u006d\u006f\u0074\u0065\u0020\u0072\u0065\u0073\u0074\u0061\u0072\u0074": "\uc6d0\uaca9\u0020\uc7ac\uc2dc\uc791\u0020\ud5c8\uc6a9",
