    "\u0041\u0075\u0074\u0068\u0065\u006e\u0074\u0069\u0063\u0061\u0074\u0069\u006f\u006e\u0020\u0052\u0065\u0071\u0075\u0069\u0072\u0065\u0064": "\uc778\uc99d\u0020\ud544\uc694",
    "\u0041\u0075\u0074\u0068\u0065\u006e\u0074\u0069\u0063\u0061\u0074\u0065": "\uc778\uc99d",
