    "\u0044\u006f\u0077\u006e\u006c\u006f\u0061\u0064": "\ub2e4\uc6b4\ub85c\ub4dc",
    "\u0055\u0070\u006c\u006f\u0061\u0064\u0020\u0066\u006f\u006c\u0064\u0065\u0072": "\ud3f4\ub354\u0020\uc5c5\ub85c\ub4dc",
    "\u0055\u0070\u006c\u006f\u0061\u0064\u0020\u0066\u0069\u006c\u0065\u0073": "\ud30c\uc77c\u0020\uc5c5\ub85c\ub4dc",
    "\u0043\u006c\u0069\u0070\u0062\u006f\u0061\u0072\u0064\u0020\u0069\u0073\u0020\u0073\u0079\u006e\u0063\u0068\u0072\u006f\u006e\u0069\u007a\u0065\u0064": "\ud074\ub9bd\ubcf4\ub4dc\uac00\u0020\ub3d9\uae30\ud654\ub418\uc5c8\uc2b5\ub2c8\ub2e4",
    "\u0055\u0070\u0064\u0061\u0074\u0065\u0020\u0063\u006c\u0069\u0065\u006e\u0074\u0020\u0063\u006c\u0069\u0070\u0062\u006f\u0061\u0072\u0064": "\ud074\ub77c\uc774\uc5b8\ud2b8\u0020\ud074\ub9bd\ubcf4\ub4dc\u0020\uc5c5\ub370\uc774\ud2b8",
