    "\u0041\u0063\u0063\u0065\u0073\u0073\u0069\u0062\u006c\u0065\u0020\u0064\u0065\u0076\u0069\u0063\u0065\u0073": "\uc561\uc138\uc2a4\u0020\uac00\ub2a5\ud55c\u0020\uc7a5\uce58",
    "\u0075\u0070\u0067\u0072\u0061\u0064\u0065\u005f\u0072\u0065\u006d\u006f\u0074\u0065\u005f\u0072\u0075\u0073\u0074\u0064\u0065\u0073\u006b\u005f\u0063\u006c\u0069\u0065\u006e\u0074\u005f\u0074\u006f\u005f\u007b\u007d\u005f\u0074\u0069\u0070": "\u0052\u0075\u0073\u0074\u0044\u0065\u0073\u006b\u0020\ud074\ub77c\uc774\uc5b8\ud2b8\ub97c\u0020\uc6d0\uaca9\u0020\ubc84\uc804\u0020\u007b\u007d\u0020\uc774\uc0c1\uc73c\ub85c\u0020\uc5c5\uadf8\ub808\uc774\ub4dc\ud574\u0020\uc8fc\uc138\uc694\u0021",
    "\u0064\u0033\u0064\u005f\u0072\u0065\u006e\u0064\u0065\u0072\u005f\u0074\u0069\u0070": "\u0044\u0033\u0044\u0020\ub80c\ub354\ub9c1\uc774\u0020\ud65c\uc131\ud654\ub418\uba74\u0020\uc77c\ubd80\u0020\uae30\uae30\uc5d0\uc11c\ub294\u0020\uc6d0\uaca9\u0020\ud654\uba74\uc774\u0020\uac80\uc740\uc0c9\uc73c\ub85c\u0020\ud45c\uc2dc\ub420\u0020\uc218\u0020\uc788\uc2b5\ub2c8\ub2e4\u002e",
    "\u0055\u0073\u0065\u0020\u0044\u0033\u0044\u0020\u0072\u0065\u006e\u0064\u0065\u0072\u0069\u006e\u0067": "\u0044\u0033\u0044\u0020\ub80c\ub354\ub9c1\u0020\uc0ac\uc6a9",
    "\u0050\u0072\u0069\u006e\u0074\u0065\u0072": "\ud504\ub9b0\ud130",
