    "\u0052\u0065\u006d\u006f\u0074\u0065\u0020\u0043\u006f\u006d\u0070\u0075\u0074\u0065\u0072": "\u004e\u0075\u006f\u0074\u006f\u006c\u0069\u006e\u0069\u0073\u0020\u006b\u006f\u006d\u0070\u0069\u0075\u0074\u0065\u0072\u0069\u0073",
    "\u004c\u006f\u0063\u0061\u006c\u0020\u0043\u006f\u006d\u0070\u0075\u0074\u0065\u0072": "\u0160\u0069\u0073\u0020\u006b\u006f\u006d\u0070\u0069\u0075\u0074\u0065\u0072\u0069\u0073",
    "\u0043\u006f\u006e\u0066\u0069\u0072\u006d\u0020\u0044\u0065\u006c\u0065\u0074\u0065": "\u0050\u0061\u0074\u0076\u0069\u0072\u0074\u0069\u006e\u0074\u0069\u0020\u0069\u0161\u0074\u0072\u0079\u006e\u0069\u006d\u0105",
