    "\u0053\u0065\u0063\u0075\u0072\u0065\u0020\u0043\u006f\u006e\u006e\u0065\u0063\u0074\u0069\u006f\u006e": "\u0053\u0061\u0075\u0067\u0075\u0073\u0020\u0072\u0079\u0161\u0079\u0073",
    "\u0049\u006e\u0073\u0065\u0063\u0075\u0072\u0065\u0020\u0043\u006f\u006e\u006e\u0065\u0063\u0074\u0069\u006f\u006e": "\u004e\u0065\u0073\u0061\u0075\u0067\u0075\u0073\u0020\u0072\u0079\u0161\u0079\u0073",
    "\u0053\u0063\u0061\u006c\u0065\u0020\u006f\u0072\u0069\u0067\u0069\u006e\u0061\u006c": "\u0050\u0061\u006b\u0065\u0069\u0073\u0074\u0069\u0020\u006f\u0072\u0069\u0067\u0069\u006e\u0061\u006c\u0173\u0020\u006d\u0061\u0073\u0074\u0065\u006c\u012f",
