    "\u0044\u0061\u0072\u006b\u0020\u0054\u0068\u0065\u006d\u0065": "\u0054\u0061\u006d\u0073\u0069\u006f\u006a\u0069\u0020\u0074\u0065\u006d\u0061",
    "\u004c\u0069\u0067\u0068\u0074\u0020\u0054\u0068\u0065\u006d\u0065": "\u0160\u0076\u0069\u0065\u0073\u0069\u0020\u0074\u0065\u006d\u0061",
