    "\u0055\u006e\u0070\u0069\u006e\u0020\u0054\u006f\u006f\u006c\u0062\u0061\u0072": "\u0057\u0065\u0072\u006b\u0062\u0061\u006c\u006b\u0020\u004c\u006f\u0073\u006d\u0061\u006b\u0065\u006e",
    "\u0052\u0065\u0063\u006f\u0072\u0064\u0069\u006e\u0067": "\u004f\u0070\u006e\u0065\u006d\u0065\u006e",
    "\u0044\u0069\u0072\u0065\u0063\u0074\u006f\u0072\u0079": "\u004d\u0061\u0070",
    "\u0041\u0075\u0074\u006f\u006d\u0061\u0074\u0069\u0063\u0061\u006c\u006c\u0079\u0020\u0072\u0065\u0063\u006f\u0072\u0064\u0020\u0069\u006e\u0063\u006f\u006d\u0069\u006e\u0067\u0020\u0073\u0065\u0073\u0073\u0069\u006f\u006e\u0073": "\u0049\u006e\u006b\u006f\u006d\u0065\u006e\u0064\u0065\u0020\u0073\u0065\u0073\u0073\u0069\u0065\u0073\u0020\u0061\u0075\u0074\u006f\u006d\u0061\u0074\u0069\u0073\u0063\u0068\u0020\u006f\u0070\u006e\u0065\u006d\u0065\u006e",
    "\u0041\u0075\u0074\u006f\u006d\u0061\u0074\u0069\u0063\u0061\u006c\u006c\u0079\u0020\u0072\u0065\u0063\u006f\u0072\u0064\u0020\u006f\u0075\u0074\u0067\u006f\u0069\u006e\u0067\u0020\u0073\u0065\u0073\u0073\u0069\u006f\u006e\u0073": "\u0055\u0069\u0074\u0067\u0061\u0061\u006e\u0064\u0065\u0020\u0073\u0065\u0073\u0073\u0069\u0065\u0073\u0020\u0061\u0075\u0074\u006f\u006d\u0061\u0074\u0069\u0073\u0063\u0068\u0020\u006f\u0070\u006e\u0065\u006d\u0065\u006e",
    "\u0043\u0068\u0061\u006e\u0067\u0065": "\u0041\u0061\u006e\u0070\u0061\u0073\u0073\u0065\u006e",
