    "\u0048\u006f\u006d\u0065": "\u0050\u00e0\u0067\u0069\u006e\u0061\u0020\u0070\u0072\u0069\u006e\u0074\u007a\u0069\u0070\u0061\u006c\u0065",
    "\u0041\u0075\u0064\u0069\u006f\u0020\u0049\u006e\u0070\u0075\u0074": "\u0049\u006e\u0074\u0072\u0061\u0064\u0061\u0020\u00e0\u0075\u0064\u0069\u006f",
    "\u0045\u006e\u0068\u0061\u006e\u0063\u0065\u006d\u0065\u006e\u0074\u0073": "\u004d\u0065\u0067\u0069\u006f\u0072\u006f\u0073",
    "\u0048\u0061\u0072\u0064\u0077\u0061\u0072\u0065\u0020\u0043\u006f\u0064\u0065\u0063": "\u0043\u006f\u0064\u0069\u0066\u0069\u0063\u0061\u0064\u006f\u0072\u0065\u0020\u0066\u00ec\u0073\u0069\u0063\u0075\u0020\u0028\u0068\u0061\u0072\u0064\u0077\u0061\u0072\u0065\u0029",
    "\u0041\u0064\u0061\u0070\u0074\u0069\u0076\u0065\u0020\u0062\u0069\u0074\u0072\u0061\u0074\u0065": "\u0056\u0065\u006c\u006f\u0074\u007a\u0069\u0064\u0061\u0064\u0065\u0020\u0064\u0065\u0020\u0062\u0069\u0074\u0073\u0020\u0061\u0064\u0061\u0074\u0069\u0076\u0061",
