    "\u0054\u006f\u006f\u0020\u0066\u0072\u0065\u0071\u0075\u0065\u006e\u0074": "\u0054\u0072\u006f\u0070\u0075\u0020\u0066\u0069\u0074\u0069\u0061\u006e\u0075",
    "\u0043\u0061\u006e\u0063\u0065\u006c": "\u0041\u006e\u006e\u0075\u006c\u006c\u0061",
