    "\u0053\u0074\u006f\u0070\u0020\u0073\u0065\u0072\u0076\u0069\u0063\u0065": "\u0055\u0073\u0074\u0061\u0076\u0069\u0020\u0073\u0074\u006f\u0072\u0069\u0074\u0065\u0076",
    "\u0043\u0068\u0061\u006e\u0067\u0065\u0020\u0049\u0044": "\u0053\u0070\u0072\u0065\u006d\u0065\u006e\u0069\u0020\u0049\u0044",
    "\u0059\u006f\u0075\u0072\u0020\u006e\u0065\u0077\u0020\u0049\u0044": "\u0056\u0061\u0161\u0020\u006e\u006f\u0076\u0020\u0049\u0044",
    "\u006c\u0065\u006e\u0067\u0074\u0068\u0020\u0025\u006d\u0069\u006e\u0025\u0020\u0074\u006f\u0020\u0025\u006d\u0061\u0078\u0025": "\u0064\u006f\u006c\u017e\u0069\u006e\u0061\u0020\u006f\u0064\u0020\u0025\u006d\u0069\u006e\u0025\u0020\u0064\u006f\u0020\u0025\u006d\u0061\u0078\u0025",
