    "\u0041\u0050\u0049\u0020\u0053\u0065\u0072\u0076\u0065\u0072": "\u0041\u0050\u0049\u0020\u0073\u0074\u0072\u0065\u017e\u006e\u0069\u006b",
    "\u0069\u006e\u0076\u0061\u006c\u0069\u0064\u005f\u0068\u0074\u0074\u0070": "\u006d\u006f\u0072\u0061\u0020\u0073\u0065\u0020\u007a\u0061\u010d\u0065\u0074\u0069\u0020\u0073\u0020\u0068\u0074\u0074\u0070\u003a\u002f\u002f\u0020\u0061\u006c\u0069\u0020\u0068\u0074\u0074\u0070\u0073\u003a\u002f\u002f",
