    "\u0052\u0065\u006d\u006f\u0074\u0065\u0020\u0043\u006f\u006d\u0070\u0075\u0074\u0065\u0072": "\u004f\u0064\u0064\u0061\u006c\u006a\u0065\u006e\u0069\u0020\u0072\u0061\u010d\u0075\u006e\u0061\u006c\u006e\u0069\u006b",
    "\u004c\u006f\u0063\u0061\u006c\u0020\u0043\u006f\u006d\u0070\u0075\u0074\u0065\u0072": "\u004c\u006f\u006b\u0061\u006c\u006e\u0069\u0020\u0072\u0061\u010d\u0075\u006e\u0061\u006c\u006e\u0069\u006b",
    "\u0043\u006f\u006e\u0066\u0069\u0072\u006d\u0020\u0044\u0065\u006c\u0065\u0074\u0065": "\u0050\u006f\u0074\u0072\u0064\u0069\u0020\u0069\u007a\u0062\u0072\u0069\u0073",
    "\u0044\u0065\u006c\u0065\u0074\u0065": "\u0049\u007a\u0062\u0072\u0069\u0161\u0069",
