    "\u0053\u0070\u0065\u0065\u0064": "\u0048\u0069\u0074\u0072\u006f\u0073\u0074",
    "\u0043\u0075\u0073\u0074\u006f\u006d\u0020\u0049\u006d\u0061\u0067\u0065\u0020\u0051\u0075\u0061\u006c\u0069\u0074\u0079": "\u004b\u0061\u006b\u006f\u0076\u006f\u0073\u0074\u0020\u0073\u006c\u0069\u006b\u0065\u0020\u0070\u006f\u0020\u006d\u0065\u0072\u0069",
    "\u0050\u0072\u0069\u0076\u0061\u0063\u0079\u0020\u006d\u006f\u0064\u0065": "\u005a\u0061\u0073\u0065\u0062\u006e\u0069\u0020\u006e\u0061\u010d\u0069\u006e",
    "\u0042\u006c\u006f\u0063\u006b\u0020\u0075\u0073\u0065\u0072\u0020\u0069\u006e\u0070\u0075\u0074": "\u004f\u006e\u0065\u006d\u006f\u0067\u006f\u010d\u0069\u0020\u0075\u0070\u006f\u0072\u0061\u0062\u006e\u0069\u006b\u006f\u0076\u0020\u0076\u006e\u006f\u0073",
    "\u0055\u006e\u0062\u006c\u006f\u0063\u006b\u0020\u0075\u0073\u0065\u0072\u0020\u0069\u006e\u0070\u0075\u0074": "\u004f\u006d\u006f\u0067\u006f\u010d\u0069\u0020\u0075\u0070\u006f\u0072\u0061\u0062\u006e\u0069\u006b\u006f\u0076\u0020\u0076\u006e\u006f\u0073",
