    "\u004f\u0072\u0069\u0067\u0069\u006e\u0061\u006c": "\u004f\u0072\u0069\u0067\u0069\u006e\u0061\u006c\u006e\u006f",
    "\u0053\u0068\u0072\u0069\u006e\u006b": "\u0053\u006b\u0072\u010d\u0069",
