    "\u0053\u0063\u0072\u006f\u006c\u006c\u0041\u0075\u0074\u006f": "\u0053\u0061\u006d\u006f\u0064\u0065\u006a\u006e\u006f\u0020\u0064\u0072\u0073\u0065\u006e\u006a\u0065",
    "\u0047\u006f\u006f\u0064\u0020\u0069\u006d\u0061\u0067\u0065\u0020\u0071\u0075\u0061\u006c\u0069\u0074\u0079": "\u0056\u0069\u0073\u006f\u006b\u0061\u0020\u006b\u0061\u006b\u006f\u0076\u006f\u0073\u0074\u0020\u0073\u006c\u0069\u006b\u0065",
    "\u0042\u0061\u006c\u0061\u006e\u0063\u0065\u0064": "\u0055\u0072\u0061\u0076\u006e\u006f\u0074\u0065\u017e\u0065\u006e\u006f",
    "\u004f\u0070\u0074\u0069\u006d\u0069\u007a\u0065\u0020\u0072\u0065\u0061\u0063\u0074\u0069\u006f\u006e\u0020\u0074\u0069\u006d\u0065": "\u004f\u0070\u0074\u0069\u006d\u0069\u0072\u0061\u006a\u0020\u006f\u0064\u007a\u0069\u0076\u006e\u0069\u0020\u010d\u0061\u0073",
