    "\u0044\u0069\u0073\u0061\u0062\u006c\u0065\u0020\u0063\u006c\u0069\u0070\u0062\u006f\u0061\u0072\u0064": "\u004f\u006e\u0065\u006d\u006f\u0067\u006f\u010d\u0069\u0020\u006f\u0064\u006c\u006f\u017e\u0069\u0161\u010d\u0065",
    "\u004c\u006f\u0063\u006b\u0020\u0061\u0066\u0074\u0065\u0072\u0020\u0073\u0065\u0073\u0073\u0069\u006f\u006e\u0020\u0065\u006e\u0064": "\u005a\u0061\u006b\u006c\u0065\u006e\u0069\u0020\u006f\u0062\u0020\u006b\u006f\u006e\u0063\u0075\u0020\u0073\u0065\u006a\u0065",
    "\u0049\u006e\u0073\u0065\u0072\u0074\u0020\u0043\u0074\u0072\u006c\u0020\u002b\u0020\u0041\u006c\u0074\u0020\u002b\u0020\u0044\u0065\u006c": "\u0056\u0073\u0074\u0061\u0076\u0069\u0020\u0043\u0074\u0072\u006c\u0020\u002b\u0020\u0041\u006c\u0074\u0020\u002b\u0020\u0044\u0065\u006c",
