    "\u0057\u0072\u006f\u006e\u0067\u0020\u0050\u0061\u0073\u0073\u0077\u006f\u0072\u0064": "\u0050\u006f\u0067\u0072\u0065\u0161\u006e\u0061\u0020\u006c\u006f\u007a\u0069\u006e\u006b\u0061",
    "\u0044\u006f\u0020\u0079\u006f\u0075\u0020\u0077\u0061\u006e\u0074\u0020\u0074\u006f\u0020\u0065\u006e\u0074\u0065\u0072\u0020\u0061\u0067\u0061\u0069\u006e\u003f": "\u017d\u0065\u006c\u0069\u0074\u0065\u0020\u006c\u0069\u0020\u0064\u0061\u0020\u0075\u006e\u0065\u0073\u0065\u0074\u0065\u0020\u0070\u006f\u006e\u006f\u0076\u006f\u003f",
