    "\u004c\u006f\u0063\u0061\u006c\u0020\u0043\u006f\u006d\u0070\u0075\u0074\u0065\u0072": "\u004c\u006f\u006b\u0061\u006c\u006e\u0069\u0020\u0072\u0061\u010d\u0075\u006e\u0061\u0072",
    "\u0043\u006f\u006e\u0066\u0069\u0072\u006d\u0020\u0044\u0065\u006c\u0065\u0074\u0065": "\u0050\u006f\u0074\u0076\u0072\u0064\u0069\u0074\u0065\u0020\u0062\u0072\u0069\u0073\u0061\u006e\u006a\u0065",
