    "\u0053\u0068\u0061\u0072\u0065\u0020\u0073\u0063\u0072\u0065\u0065\u006e": "\u0044\u0065\u006c\u0061\u0020\u0073\u006b\u00e4\u0072\u006d",
    "\u0043\u0068\u0061\u0074": "\u0043\u0068\u0061\u0074\u0074",
