    "\u0046\u0069\u0078\u0020\u0069\u0074": "\u0044\u00fc\u007a\u0065\u006e\u006c\u0065",
    "\u0057\u0061\u0072\u006e\u0069\u006e\u0067": "\u0055\u0079\u0061\u0072\u0131",
