    "\u0052\u0065\u006d\u006f\u0074\u0065\u0020\u0049\u0044": "\u0412\u0456\u0434\u0434\u0430\u043b\u0435\u043d\u0438\u0439\u0020\u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440",
