    "\u004c\u0065\u0066\u0074\u0020\u004d\u006f\u0075\u0073\u0065": "\u041b\u0456\u0432\u0430\u0020\u043a\u043d\u043e\u043f\u043a\u0430\u0020\u043c\u0438\u0448\u0456",
